from fastapi import APIRouter, Depends, HTTPException, status
import hvac

router = APIRouter(prefix="/infrastructure/db-roles")

@router.post("/{role_name}/lease-credentials")
async def lease_database_credentials(
    role_name: str,
    vault_client: hvac.Client = Depends(get_vault_client),
    user: User = Depends(get_current_user)
):
    allowed_role_prefix = f"role_{user.tenant_id}_"
    if not role_name.startswith(allowed_role_prefix) and not user.is_platform_admin:
        raise HTTPException(status_code=status.HTTP_403_FORBIDDEN, detail="Not authorized to lease credentials for this role")

    try:
        credentials = vault_client.secrets.database.generate_credentials(
            name=role_name,
            mount_point="database"
        )
        return {
            "role": role_name,
            "username": credentials["data"]["username"],
            "password": credentials["data"]["password"],
            "lease_duration": credentials["lease_duration"]
        }
    except hvac.exceptions.VaultError as e:
        raise HTTPException(status_code=status.HTTP_400_BAD_REQUEST, detail=f"Failed to lease credentials: {e}")
